/* Explicit screen composition. Domain logic and durable data stay in their existing modules. */
(function(){
  const nav=window.REP_NAVIGATION,core=window.REP_CORE_PAGES,preferences=window.REP_TRAINING_PREFERENCES;
  const route=id=>nav.navigate(id),date=()=>isoDay();
  preferences.normalize(state);
  let library={query:'',equipment:'all',muscle:'all'},historyFilter={query:'',from:'',to:''};
  function enter(view,tab){stopExerciseClock();stopSessionClock();document.body.classList.remove('workout-mode','workout-complete-mode','rest-mode-active');timerDock.classList.add('is-hidden');timerDock.setAttribute('inert','');if(state.timer?.interval){clearInterval(state.timer.interval);state.timer.interval=null;}state.view=view;state.activeTab=tab;persistDebounced();updatePrimaryTabs();}
  function heading(title,description=''){return `<header class="page-heading"><h1>${esc(title)}</h1>${description?`<p>${esc(description)}</p>`:''}</header>`;}
  function sheet(title,content,bind=()=>{}){
    const overlay=document.createElement('div');overlay.className='rep-modal-backdrop';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label',title);
    overlay.innerHTML=REP_SAFE_DOM.sanitize(`<section class="rep-modal-sheet"><header class="sheet-header"><h2>${esc(title)}</h2><button class="sheet-close" aria-label="Close">×</button></header>${content}</section>`);
    const previous=document.activeElement;let closing=false;
    const close=async()=>{if(closing)return;closing=true;await window.REP_MOTION.dismiss(overlay);if(previous?.isConnected)previous.focus();};
    overlay.querySelector('.sheet-close').onclick=close;overlay.onclick=e=>{if(e.target===overlay)close();};
    overlay.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();close();}if(event.key==='Tab'){const controls=[...overlay.querySelectorAll('button,a[href],input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled&&el.getClientRects().length);const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
    document.body.append(overlay);bind(overlay,close);overlay.querySelector('button,input')?.focus();return overlay;
  }
  function readiness(){
    const engine=window.REP_HEALTH_ENGINE,value=engine.readiness(state,date(),state.healthProfile),advice=engine.trainingRecommendation(state,date(),state.healthProfile,value);
    const imported=state.lastVitalsImportDate,age=daysSinceVitalsImport();
    return {value,advice,age,source:imported?`Health data ${age===0?'today':`${age} day${age===1?'':'s'} ago`}`:'No imported health data',confidence:value.confidence||'low'};
  }
  function readinessMarkup(){const r=readiness();return `<section class="readiness-note"><div><h2>${esc(r.advice.title)}</h2><p>${esc(r.advice.detail||r.advice.message||'Use your warm-up as the final check. You can log manually without a watch.')}</p></div><details><summary>Why this recommendation?</summary><p>${esc(r.source)} · ${esc(r.confidence)} confidence</p><p>${r.value.score===null?'More recovery observations are needed.':`Wellness estimate: ${r.value.score}%`}</p><p>${esc((r.value.reasons||[]).map(x=>typeof x==='string'?x:x.detail||x.label||'').filter(Boolean).join(' '))}</p></details></section>`;}
  function saveStatus(){const queued=window.REP_SYNC_OUTBOX?.summary(state.syncQueue)?.total||0;return `<button type="button" class="save-status ${queued?'has-pending':''}" data-save-status>${queued?`Saved on device · ${queued} waiting to sync`:state.lastSyncedAt?'Saved on device · records synced':'Saved on device'}</button>`;}
  function bindSaveStatus(){document.querySelector('[data-save-status]')?.addEventListener('click',()=>route('settings-sync'));}
  function today(){
    enter('home-overview','home');const resume=REP_TRAINING_SESSION.isResumableWorkout(state,sessions),plan=window.REP_ENHANCEMENTS_UI.adaptiveTodayPlan(),id=resume?state.session:plan.targetSession,s=sessions[id]||{name:"Recovery day",meta:"No scheduled workout",description:plan.detail,exercises:[]},ls=sessionText(id,s),duration=s.duration||ls.meta.match(/\d+[–-]\d+ min|\d+ min/)?.[0]||`${s.exercises.length} exercises`;
    app.innerHTML=REP_SAFE_DOM.sanitize(`${heading('Today',new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'}))}<section class="today-session" data-today-session><div><span class="muted">${resume?'In progress':"Today's workout"}</span><h2>${esc(ls.name)}</h2><p>${esc(duration)} · ${s.exercises.length} exercises${resume?` · Exercise ${state.index+1}`:''}</p></div><button class="primary-action" data-today-start>${resume?'Resume workout':id?'Start workout':'Review recovery'}</button><button class="quiet-action" data-today-preview>Review exercises</button></section>${readinessMarkup()}<nav class="quick-actions" aria-label="Quick actions"><button data-adjust-today>Adjust today</button><button data-today-activity>Log activity</button><button data-today-food>Meal / water</button><button data-today-checkin>Check-in</button></nav>${saveStatus()}<section data-daily-routines></section>`);
    document.querySelector('[data-today-start]').onclick=()=>{if(!id){route("health-vitals");return;}if(!resume)REP_ADAPTIVE_COACH.applyPlan(state,plan,sessions);startSession(id);};
    document.querySelector('[data-today-preview]').onclick=()=>id?showSessionPreview(id):route('training-program');
    document.querySelector('[data-adjust-today]').onclick=()=>sheet('Adjust today',`<p>Choose a lighter option using your existing plan.</p><button class="primary-action" data-adjust-light>Short workout</button><button data-adjust-schedule>Move this workout</button>`,(root,close)=>{root.querySelector('[data-adjust-light]').onclick=()=>{close();renderBadDay();};root.querySelector('[data-adjust-schedule]').onclick=()=>{close();route('settings-schedule');};});
    document.querySelector('[data-today-activity]').onclick=()=>showLogActivity();document.querySelector('[data-today-food]').onclick=()=>route('nutrition-log');document.querySelector('[data-today-checkin]').onclick=checkin;
    window.REP_HABITS.mount();bindSaveStatus();
  }
  function checkin(){sheet('Quick recovery check-in',window.REP_HEALTH_UI.checkinMarkup(),(_root,close)=>window.REP_HEALTH_UI.bind({onSaved:()=>{close();today();showToast('Check-in saved on device.');}}));}
  function routineCard(id,s){const favourite=state.routineFavourites.includes(id),resume=REP_TRAINING_SESSION.isResumableWorkout(state,sessions,id);return `<article class="routine-card" data-routine-card="${esc(id)}"><div><h2>${esc(s.name)}</h2><p>${s.exercises.length} exercises${s.duration?` · ${esc(s.duration)}`:''}</p></div><button data-routine-favourite="${esc(id)}" aria-pressed="${favourite}" aria-label="${favourite?'Unfavourite':'Favourite'} ${esc(s.name)}">${favourite?'★':'☆'}</button><div class="routine-actions"><button class="primary-action" data-session="${esc(id)}">${resume?'Resume':'Preview'}</button>${id.startsWith('custom-')?`<button data-edit-custom="${esc(id)}">Edit</button>`:''}</div></article>`;}
  function train(){
    enter('home','train');state.trainingView='program';window.REP_CUSTOM_WORKOUTS.getCustomRoutines();
    const ids=Object.keys(sessions).filter(id=>!['bad','gymLite'].includes(id)).sort((a,b)=>Number(state.routineFavourites.includes(b))-Number(state.routineFavourites.includes(a)));
    app.innerHTML=REP_SAFE_DOM.sanitize(`${heading('Train','Your routines, this week, and exercise technique.')}<nav class="screen-shortcuts" aria-label="Training shortcuts"><button data-train-jump="routines">Routines</button><button data-train-jump="library">Find exercise</button><button data-train-jump="schedule">Schedule</button></nav><section class="train-week"><h2>This week</h2><div class="week-plan">${window.REP_ENHANCEMENTS_UI.dayNames.map(day=>{const focus=window.REP_ENHANCEMENTS_UI.daySchedule(day)?.focus||state.preferences?.schedule?.[day]?.focus||'rest';return `<div><span>${esc(day.slice(0,3))}</span><strong>${esc(window.REP_ENHANCEMENTS_UI.focusLabel(focus))}</strong></div>`;}).join('')}</div><button data-train-schedule>Edit schedule</button></section><div class="section-title"><h2>Workout routines</h2><button class="primary-action" data-create-new-routine>New routine</button></div><section class="routine-list">${ids.map(id=>routineCard(id,sessions[id])).join('')}</section><section class="exercise-library"><h2>Exercise library</h2><label>Search exercises<input type="search" data-library-search value="${esc(library.query)}" placeholder="Exercise or muscle"></label><div class="library-filters"><label>Equipment<select data-library-equipment>${['all','machines','dumbbells','barbell','bands','bodyweight','cardio'].map(x=>`<option value="${x}" ${library.equipment===x?'selected':''}>${x==='all'?'All equipment':x}</option>`).join('')}</select></label><label>Muscle<select data-library-muscle><option value="all">All muscles</option>${[...new Set(REP_EXERCISES.list().flatMap(x=>x.muscleTags))].sort().map(x=>`<option ${library.muscle===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label></div><p data-library-count role="status"></p><div data-library-results></div></section><details class="supporting-details"><summary>Plan tools and safety</summary><button data-train-review>Technique review</button><button data-train-planreview>Program checkpoint</button><button data-train-export>Export / share plan</button></details>`);
    app.querySelectorAll('[data-train-jump]').forEach(button=>button.onclick=()=>{const target=app.querySelector({routines:'.routine-list',library:'.exercise-library',schedule:'.train-week'}[button.dataset.trainJump]);target?.scrollIntoView({block:'start',behavior:'instant'});if(button.dataset.trainJump==='library')target.querySelector('input')?.focus({preventScroll:true});});
    document.querySelectorAll('[data-session]').forEach(b=>b.onclick=()=>showSessionPreview(b.dataset.session));document.querySelectorAll('[data-routine-favourite]').forEach(b=>b.onclick=()=>{preferences.toggleFavourite(state,b.dataset.routineFavourite);persist();train();});document.querySelectorAll('[data-edit-custom]').forEach(b=>b.onclick=()=>window.REP_CUSTOM_WORKOUTS.openRoutineBuilderModal(b.dataset.editCustom));
    document.querySelector('[data-create-new-routine]').onclick=()=>window.REP_CUSTOM_WORKOUTS.openRoutineBuilderModal();document.querySelector('[data-train-schedule]').onclick=()=>route('settings-schedule');document.querySelector('[data-train-review]').onclick=renderReview;document.querySelector('[data-train-planreview]').onclick=renderProgramReview;document.querySelector('[data-train-export]').onclick=()=>{sheet('Plan tools','<button data-plan-export>Export plan</button>',(root)=>root.querySelector('[data-plan-export]').onclick=exportData);};
    for(const [selector,key] of [['[data-library-search]','query'],['[data-library-equipment]','equipment'],['[data-library-muscle]','muscle']])document.querySelector(selector).addEventListener(key==='query'?'input':'change',e=>{library[key]=e.target.value;renderLibrary();});renderLibrary();
  }
  function renderLibrary(){const query=library.query.toLowerCase().trim(),rows=REP_EXERCISES.list().filter(x=>(!query||`${x.name} ${x.targetMuscles||''}`.toLowerCase().includes(query))&&(library.equipment==='all'||x.equipmentTags.includes(library.equipment))&&(library.muscle==='all'||x.muscleTags.includes(library.muscle)));const results=document.querySelector('[data-library-results]');if(!results)return;document.querySelector('[data-library-count]').textContent=`${rows.length} exercises`;results.innerHTML=REP_SAFE_DOM.sanitize(rows.map(x=>`<button class="library-row" data-library-exercise="${esc(x.name)}"><strong>${esc(x.name)}</strong><span>${esc(x.targetMuscles||x.category||'General movement')}</span></button>`).join('')||'<p>No matching exercise. Change your search or filters.</p>');results.querySelectorAll('[data-library-exercise]').forEach(b=>b.onclick=()=>exerciseDetails(b.dataset.libraryExercise));}
  function exerciseDetails(name){const item=REP_EXERCISES.get(name);sheet(name,`<div class="library-demo">${REP_MEDIA_PLAYER.markup(item,{preview:true,context:'library'})}</div><p>${esc(item.setup)}</p><p>${esc(item.execution)}</p><p><strong>Key cue:</strong> ${esc(item.cues)}</p><p><strong>Avoid:</strong> ${esc(item.avoid)}</p>`,()=>REP_MEDIA_PLAYER.mount());}
  function nutrition(){
    enter('nutrition','food');core.nutrition();window.REP_ENHANCEMENTS_UI.nutrition();
    const head=app.querySelector('.food-head'),disclosure=app.querySelector('.nutrition-disclosure');if(head)head.innerHTML=REP_SAFE_DOM.sanitize(heading('Nutrition','Today’s food, water, and quick meal entry.'));
    app.querySelector('.connection-banner')?.remove();
    const composer=app.querySelector('.meal-composer'),dashboard=app.querySelector('.macro-dashboard');
    const summary=document.createElement('section');summary.className='nutrition-summary';const totals=foodTotals(todayFoodEntries()),profile=foodProfile(),water=Number(state.water[isoDay()])||0;
    summary.innerHTML=REP_SAFE_DOM.sanitize(`<h2>Today so far</h2><dl><div><dt>Energy</dt><dd>${Math.round(totals.calories)}<span>/ ${profile.calories} kcal</span></dd></div><div><dt>Protein</dt><dd>${Math.round(totals.protein_g)}<span>/ ${profile.protein} g</span></dd></div><div><dt>Water</dt><dd>${esc(window.waterDisplay(water))}<span>/ ${esc(window.waterDisplay(profile.water))}</span></dd></div></dl>`);
    head?.after(summary);
    const shortcut=document.createElement('nav');shortcut.className='nutrition-actions';shortcut.setAttribute('aria-label','Nutrition actions');shortcut.innerHTML=REP_SAFE_DOM.sanitize('<button class="primary-action" data-nutrition-log>Log meal</button><button data-nutrition-water>Water</button>');summary.after(shortcut);
    shortcut.querySelector('[data-nutrition-log]').onclick=()=>route('nutrition-log');shortcut.querySelector('[data-nutrition-water]').onclick=()=>{state.nutritionView='today';nutrition();app.querySelector('.water-card')?.scrollIntoView({block:'center'});};
    if(state.nutritionView==='today'){
      const navSection=app.querySelector('[data-nav-for="nutrition"]'),recent=app.querySelector('.food-log');
      if(recent&&navSection)navSection.after(recent);
      if(dashboard){const details=document.createElement('details');details.className='nutrition-details';details.innerHTML=REP_SAFE_DOM.sanitize('<summary>Targets and nutrition breakdown</summary>');dashboard.replaceWith(details);details.append(dashboard);}
      const reminder=app.querySelector('.reminder-strip');if(reminder){const details=document.createElement('details');details.className='nutrition-details';details.innerHTML=REP_SAFE_DOM.sanitize('<summary>Nutrition routine and supplements</summary>');reminder.replaceWith(details);details.append(reminder);}
    }
    if(composer){composer.querySelector('.estimate-pill').textContent='Optional AI estimate';if(disclosure)composer.append(disclosure);}
    const connection=document.createElement('button');connection.className='quiet-action';connection.dataset.nutritionConnect='true';connection.textContent='Set up nutrition connections';connection.onclick=()=>route('settings-sync');app.append(connection);
    if(state.nutritionView==='log')composer?.scrollIntoView({block:'start'});
  }

  function historyMarkup(){const q=historyFilter.query.toLowerCase(),rows=(state.history||[]).filter(x=>{const day=String(x.date||'').slice(0,10);return (!historyFilter.from||day>=historyFilter.from)&&(!historyFilter.to||day<=historyFilter.to)&&(!q||`${sessions[x.session]?.name||x.activityLabel||x.session} ${(x.entries||[]).map(e=>e.exercise).join(' ')}`.toLowerCase().includes(q));});return `<p>${rows.length} sessions</p>${rows.map(x=>`<article class="history-result"><h3>${esc(sessions[x.session]?.name||x.activityLabel||x.session)}</h3><p>${esc(String(x.date||'').slice(0,10))} · ${Math.round((Number(x.duration)||0)/60)} min · ${Number(x.sets)||0} sets</p><details><summary>Logged exercises</summary>${(x.entries||[]).map(e=>`<p>${esc(e.exercise)} · ${esc(String(e.weight||'—'))} kg · ${esc(String(e.reps||'—'))} reps${e.rpe?` · RPE ${esc(e.rpe)}`:''}</p>`).join('')||'<p>No detailed set records.</p>'}</details></article>`).join('')||'<p>Complete your first workout to see its history here.</p>'}`;}
  function progress(){
    enter('insights','insights');const weekly=REP_PRODUCT_SUITE.weeklySummary(state,undefined,REP_PERFORMANCE_INSIGHTS),model=REP_PERFORMANCE_INSIGHTS.analyze(state),lifts=model.strength?.exercises||[],selected=state.progressExercise||lifts[0]?.exercise,exercise=lifts.find(x=>x.exercise===selected),proposals=state.progressionProposals||[];
    app.innerHTML=REP_SAFE_DOM.sanitize(`${heading('Progress','Consistency, performance, and your next step.')}<nav class="screen-shortcuts" aria-label="Progress shortcuts"><button data-open-weekly>Weekly report</button><button data-open-history>Workout history</button></nav><section class="progress-overview"><h2>Am I following my plan?</h2><p class="metric-value">${weekly.completed} / ${weekly.planned}</p><p>Planned sessions completed this week${weekly.totalWorkouts>weekly.completed?` · ${weekly.totalWorkouts-weekly.completed} additional activities`:''}</p></section><section class="exercise-progress"><h2>Am I improving?</h2>${lifts.length?`<label>Exercise<select data-progress-exercise>${lifts.map(x=>`<option ${x.exercise===selected?'selected':''}>${esc(x.exercise)}</option>`).join('')}</select></label><p>${esc(exercise?.recommendation||'Establishing a baseline')} · ${exercise?.sessionCount||0} logged sessions</p>${exercise?.currentE1rm?`<p>Best estimated 1RM: ${esc(String(exercise.currentE1rm))} kg</p><p>${exercise.change28d===null?'More sessions are needed for a 28-day comparison.':`${exercise.change28d>0?'+':''}${exercise.change28d}% over 28 days`}</p>`:''}`:'<p>Log weight and reps across several sessions to see a reliable exercise trend.</p>'}</section><section class="next-step"><h2>What should I do next?</h2><p>${esc(weekly.nextAction)}</p><button class="primary-action" data-progress-train>Open routines</button>${proposals.length?`<details><summary>Next-session targets</summary>${window.REP_ENHANCEMENTS_UI.progressionCard(proposals)}</details>`:''}</section><section class="progress-history"><h2>Workout history</h2><label>Search sessions or exercises<input type="search" data-history-search value="${esc(historyFilter.query)}"></label><div class="history-dates"><label>From<input type="date" data-history-from value="${historyFilter.from}"></label><label>To<input type="date" data-history-to value="${historyFilter.to}"></label></div><div data-history-results>${historyMarkup()}</div></section><details class="supporting-details progress-analysis"><summary>Weekly report and detailed analysis</summary><div class="trends-grid"></div>${window.REP_PRODUCT_UI.weeklyCard()}${window.REP_PRODUCT_UI.experimentsCard()}${window.REP_HEALTH_UI.trendMarkup()}</details>`);
    app.querySelector('[data-open-weekly]').onclick=()=>{app.querySelector('.progress-analysis').open=true;const report=app.querySelector('[data-product-weekly]');report.scrollIntoView({block:'start',behavior:'instant'});const title=report.querySelector('h2');title.tabIndex=-1;title.focus({preventScroll:true});};app.querySelector('[data-open-history]').onclick=()=>{app.querySelector('.progress-history').scrollIntoView({block:'start',behavior:'instant'});app.querySelector('[data-history-search]').focus({preventScroll:true});};
    document.querySelector('[data-progress-train]').onclick=()=>route('training-program');document.querySelector('[data-accept-progression]')?.addEventListener('click',()=>{window.REP_ENHANCEMENTS_UI.acceptProgression(proposals);progress();});document.querySelector('[data-progress-exercise]')?.addEventListener('change',e=>{state.progressExercise=e.target.value;progress();});for(const [selector,key] of [['[data-history-search]','query'],['[data-history-from]','from'],['[data-history-to]','to']])document.querySelector(selector).addEventListener(key==='query'?'input':'change',e=>{historyFilter[key]=e.target.value;document.querySelector('[data-history-results]').innerHTML=REP_SAFE_DOM.sanitize(historyMarkup());});window.REP_PRODUCT_UI.bindWeekly(app.querySelector('[data-product-weekly]'));window.REP_PRODUCT_UI.bindExperiments(app.querySelector('[data-product-experiments]'));window.REP_PERFORMANCE_UI.mount();window.REP_HEALTH_UI.bind();
  }
  function more(){enter('more','more');app.innerHTML=REP_SAFE_DOM.sanitize(`${heading('More','Recovery, daily routines, and your settings.')}<section class="more-menu">${[['Recovery','Sleep, check-ins and measurements','health-vitals'],['Daily routines','Habits, hygiene and journal','health-wellness'],['Connections','Sync, Apple Health and Notion','settings-sync'],['Settings','Units, schedule and targets','settings-general'],['Backups & privacy','Export, restore and connected devices','settings-security']].map(([title,detail,id])=>`<button data-more-route="${id}"><strong>${title}</strong><span>${detail}</span><b aria-hidden="true">→</b></button>`).join('')}</section>${saveStatus()}`);app.querySelectorAll('[data-more-route]').forEach(b=>b.onclick=()=>route(b.dataset.moreRoute));bindSaveStatus();}
  function recovery(){
    enter('vitals','vitals');core.vitals();
    const old=document.createElement('div');while(app.firstChild)old.append(app.firstChild);
    const sleep=old.querySelector('.sleep-card');
    app.innerHTML=REP_SAFE_DOM.sanitize(`${heading('Recovery','Sleep and recovery inputs support your training.')}<button data-more-back>← More</button>${readinessMarkup()}<nav class="quick-actions"><button data-recovery-checkin>Quick check-in</button><button data-recovery-measurements>Measurements</button></nav><details class="recovery-sleep"><summary>Log sleep</summary></details><details class="supporting-details recovery-data"><summary>Health data, baselines and setup</summary>${window.REP_HEALTH_UI.trendMarkup()}</details>`);
    if(sleep)app.querySelector('.recovery-sleep').append(sleep);
    old.querySelectorAll('.hero,.strain-recovery-card,.recovery-head').forEach(x=>x.remove());app.querySelector('.recovery-data').append(old);
    app.querySelector('[data-more-back]').onclick=()=>route('more');app.querySelector('[data-recovery-checkin]').onclick=checkin;app.querySelector('[data-recovery-measurements]').onclick=()=>{app.querySelector('.recovery-data').open=true;app.querySelector('[data-body-measurement]')?.scrollIntoView({block:'center'});};window.REP_HEALTH_UI.bind({onMeasurementSaved:()=>{recovery();app.querySelector('.recovery-data').open=true;showToast('Measurements saved on device.');}});
    window.REP_PRODUCT_UI.mount();updatePrimaryTabs();
  }
  function routines(){enter('care','care');core.wellness();const oldHead=app.querySelector('.module-head,.recovery-head');if(oldHead)oldHead.innerHTML=REP_SAFE_DOM.sanitize(heading('Daily routines','Your existing hygiene, wellness and journal routines.'));const back=document.createElement('button');back.dataset.moreBack='true';back.textContent='← More';back.onclick=()=>route('more');app.prepend(back);window.REP_HABITS.mount();window.REP_PRODUCT_UI.mount();updatePrimaryTabs();}
  function guardStart(id,proceed){
    if(REP_TRAINING_SESSION.isResumableWorkout(state,sessions)&&state.session!==id){sheet('Workout in progress','<p>Resume or explicitly end the current workout before starting another.</p><button class="primary-action" data-resume-active>Resume current workout</button>',(root,close)=>root.querySelector('[data-resume-active]').onclick=()=>{close();startSession(state.session,{acknowledgeWarnings:true});});return true;}
    const r=readiness();if(r.advice.mode==='pause'){sheet('Review your recovery warning',`<p>${esc(r.advice.detail||r.advice.message||r.advice.title)}</p><button class="primary-action" data-review-recovery>Review recovery</button><button data-acknowledge-workout>Record a modified workout</button>`,(root,close)=>{root.querySelector('[data-review-recovery]').onclick=()=>{close();route('health-vitals');};root.querySelector('[data-acknowledge-workout]').onclick=()=>{close();proceed();};});return true;}return false;
  }
  window.REP_TRAINING_UI=Object.freeze({today,train,nutrition,progress,more,recovery,routines,checkin,sheet,guardStart});
  renderOverview=today;renderHome=train;renderInsights=progress;renderHistory=progress;renderNutrition=nutrition;renderVitals=recovery;renderHygiene=routines;
  document.body.classList.add('training-first-app');
  nav.register([{id:'today',path:'/today',title:'Today',activate:today},{id:'training-program',path:'/train',aliases:['/training/program','/training/today','/program-active'],title:'Train',activate:train},{id:'training-today',path:'/training/today',title:'Today',activate:today},{id:'insights',path:'/progress',aliases:['/insights'],title:'Progress',activate:progress},{id:'training-history',path:'/progress/history',aliases:['/training/history'],title:'History',activate:progress},{id:'more',path:'/more',title:'More',activate:more},{id:'health-vitals',path:'/more/recovery',aliases:['/health/vitals'],title:'Recovery',activate:recovery},{id:'health-wellness',path:'/more/routines',aliases:['/health/wellness'],title:'Daily routines',activate:routines}]);
  nav.setTabResolver(tab=>({home:'today',train:'training-program',food:'nutrition-today',insights:'insights',more:'more',health:'health-vitals',vitals:'health-vitals',care:'health-wellness'}[tab]||tab));
  window.addEventListener('rep:navigation',()=>{updatePrimaryTabs();if(['vitals','care'].includes(state.activeTab)&&!app.querySelector('[data-more-back]')){const back=document.createElement('button');back.dataset.moreBack='true';back.textContent='← More';back.onclick=()=>route('more');app.prepend(back);}});
  nav.navigate(nav.current()==='training-today'?'today':nav.current()||'today',{replace:true,focus:false,scroll:false});
  // Both overlay keyboards (iOS) and resized layouts (Android) use the same controls.
  const viewport=window.visualViewport;
  let baselineHeight=window.innerHeight,lastWidth=window.innerWidth,viewportFrame=0;
  const editable=element=>element?.matches?.('textarea,input:not([type=checkbox]):not([type=radio]):not([type=range]):not([type=file]):not([type=button]):not([type=submit])')&&!element.readOnly&&!element.disabled;
  function updateViewport(){
    viewportFrame=0;
    const scale=viewport?.scale||1,zoomed=Math.abs(scale-1)>.05,editing=editable(document.activeElement);
    const height=viewport?.height||window.innerHeight,top=viewport?.offsetTop||0;
    if(Math.abs(window.innerWidth-lastWidth)>80){baselineHeight=window.innerHeight;lastWidth=window.innerWidth;}
    if(!editing&&!zoomed)baselineHeight=window.innerHeight;
    const inset=Math.max(0,window.innerHeight-height-top);
    const open=Boolean(editing&&!zoomed&&(inset>100||baselineHeight-height>120));
    document.body.classList.toggle('is-keyboard-open',open);
    const style=document.documentElement.style;
    style.setProperty('--keyboard-bottom',`${open?Math.round(inset):0}px`);
    style.setProperty('--visible-height',`${Math.round(height)}px`);
    style.setProperty('--visible-top',`${Math.round(top)}px`);
    if(open)requestAnimationFrame(()=>{
      const input=document.activeElement;if(!editable(input))return;
      const bounds=input.getBoundingClientRect(),action=app.querySelector('.workout-action-band');
      const footer=action?.getClientRects().length?action.getBoundingClientRect().height+16:16;
      if(bounds.top<top+12||bounds.bottom>top+height-footer)input.scrollIntoView({block:'center',behavior:'instant'});
    });
  }
  const scheduleViewport=()=>{if(!viewportFrame)viewportFrame=requestAnimationFrame(updateViewport);};
  viewport?.addEventListener('resize',scheduleViewport);viewport?.addEventListener('scroll',scheduleViewport);
  window.addEventListener('resize',scheduleViewport);
  document.addEventListener('focusin',scheduleViewport);document.addEventListener('focusout',()=>setTimeout(scheduleViewport,0));
  document.addEventListener('keydown',event=>{if(event.key!=='Enter'||!event.target.matches('[data-live-log]'))return;event.preventDefault();const fields=[...app.querySelectorAll('[data-live-log]')],next=fields[fields.indexOf(event.target)+1];if(next)next.focus();else event.target.blur();});
  document.addEventListener('pointerdown',event=>{if(event.target.closest('[data-keyboard-dismiss]')){event.preventDefault();document.activeElement?.blur();scheduleViewport();}});
  document.addEventListener('click',event=>{if(event.target.closest('[data-keyboard-dismiss]')){document.activeElement?.blur();scheduleViewport();}});
  updateViewport();


})();
